package com.tekwatt.support.entity;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;import java.util.UUID;@Entity @Table(name="amc_contracts")public class AmcContract{@Id private UUID id;@Column(nullable=false,unique=true,length=40)private String contractNumber;@Column(nullable=false)private UUID tenantId;@Column(nullable=false)private UUID partnerId;@Column(nullable=false)private UUID stationId;@Column(nullable=false)private LocalDate startDate;@Column(nullable=false)private LocalDate endDate;@Column(nullable=false,precision=12,scale=2)private BigDecimal amount;@Column(nullable=false,length=3)private String currency;@Column(nullable=false,length=20)private String status;@Column(nullable=false)private Instant createdAt;protected AmcContract(){}public AmcContract(UUID t,UUID p,UUID s,LocalDate from,LocalDate to,BigDecimal amount,String currency){id=UUID.randomUUID();contractNumber="AMC-"+Instant.now().toEpochMilli();tenantId=t;partnerId=p;stationId=s;startDate=from;endDate=to;this.amount=amount;this.currency=currency;status="ACTIVE";createdAt=Instant.now();}public void status(String s){status=s;}public UUID getId(){return id;}public String getContractNumber(){return contractNumber;}public UUID getTenantId(){return tenantId;}public UUID getPartnerId(){return partnerId;}public UUID getStationId(){return stationId;}public LocalDate getStartDate(){return startDate;}public LocalDate getEndDate(){return endDate;}public BigDecimal getAmount(){return amount;}public String getCurrency(){return currency;}public String getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}}
